// ── Deterministic anomaly detection. No LLM. Same output for chat + email. ──
const TH = { volume_pct: 25, resolution_pp: 5, csat_pts: 0.3, min_sr: 30 };

const rows = $input.all().map(i => i.json);
if (!rows.length) {
  return [{ json: { error: 'no rows returned from cs_contacts', trend: null, anomaly_count: 0, anomalies: [] } }];
}

const N = v => Number(v || 0);
const curWeek  = rows[0].cur_week;
const curRows  = rows.filter(r => r.week === curWeek);
const prevRows = rows.filter(r => r.week !== curWeek);
const prevWeek = prevRows.length ? prevRows[0].week : null;

function roll(rs) {
  return rs.reduce((a, r) => ({
    sr: a.sr + N(r.sr_cnt),
    rc: a.rc + N(r.rsltn_cnt),
    rr: a.rr + N(r.rsltn_response_cnt),
    cs: a.cs + N(r.csat_sum),
    cr: a.cr + N(r.csat_response_cnt),
  }), { sr: 0, rc: 0, rr: 0, cs: 0, cr: 0 });
}

function metrics(t) {
  return {
    volume: t.sr,
    resolution_rate: t.rc ? Number(((t.rr / t.rc) * 100).toFixed(2)) : null,
    csat: t.cr ? Number((t.cs / t.cr).toFixed(2)) : null,
  };
}

const pct = (c, p) => (p ? Number((((c - p) / p) * 100).toFixed(1)) : null);
const dlt = (c, p, d) => (c != null && p != null ? Number((c - p).toFixed(d)) : null);

const curT = roll(curRows), prevT = roll(prevRows);
const cur  = metrics(curT),  prev  = metrics(prevT);

const trend = {
  current_week: curWeek,
  prior_week: prevWeek,
  volume:          { current: cur.volume,          prior: prev.volume,          change_pct: pct(cur.volume, prev.volume) },
  resolution_rate: { current: cur.resolution_rate, prior: prev.resolution_rate, change_pp:  dlt(cur.resolution_rate, prev.resolution_rate, 2) },
  csat:            { current: cur.csat,            prior: prev.csat,            change_pts: dlt(cur.csat, prev.csat, 2) },
};

function index(rs, keyFn) {
  const m = {};
  for (const r of rs) {
    const k = keyFn(r);
    if (k == null || k === '') continue;
    if (!m[k]) m[k] = { sr: 0, rc: 0, rr: 0, cs: 0, cr: 0 };
    m[k].sr += N(r.sr_cnt); m[k].rc += N(r.rsltn_cnt); m[k].rr += N(r.rsltn_response_cnt);
    m[k].cs += N(r.csat_sum); m[k].cr += N(r.csat_response_cnt);
  }
  return m;
}

const dims = [
  { name: 'country',  fn: r => r.country },
  { name: 'l1_topic', fn: r => r.l1_topic },
];

const totalVolDelta = curT.sr - prevT.sr;
const anomalies = [];

for (const d of dims) {
  const C = index(curRows, d.fn), P = index(prevRows, d.fn);
  for (const k of new Set([...Object.keys(C), ...Object.keys(P)])) {
    const ct = C[k] || { sr: 0, rc: 0, rr: 0, cs: 0, cr: 0 };
    const pt = P[k] || { sr: 0, rc: 0, rr: 0, cs: 0, cr: 0 };
    if (ct.sr < TH.min_sr && pt.sr < TH.min_sr) continue;   // sample floor
    const cm = metrics(ct), pm = metrics(pt);
    const base = { dimension: d.name, segment: k };

    const vp = pct(cm.volume, pm.volume);
    if (vp !== null && Math.abs(vp) >= TH.volume_pct) {
      anomalies.push({ ...base, metric: 'volume', prior: pm.volume, current: cm.volume,
        delta: cm.volume - pm.volume, change_pct: vp,
        contribution_pct: totalVolDelta ? Number((((cm.volume - pm.volume) / totalVolDelta) * 100).toFixed(1)) : null,
        direction: vp > 0 ? 'up' : 'down', _sev: Math.abs(vp) / TH.volume_pct });
    }

    const rp = dlt(cm.resolution_rate, pm.resolution_rate, 2);
    if (rp !== null && Math.abs(rp) >= TH.resolution_pp) {
      anomalies.push({ ...base, metric: 'resolution_rate', prior: pm.resolution_rate, current: cm.resolution_rate,
        delta_pp: rp, sample_size: ct.rc, direction: rp > 0 ? 'up' : 'down',
        _sev: Math.abs(rp) / TH.resolution_pp });
    }

    const cp = dlt(cm.csat, pm.csat, 2);
    if (cp !== null && Math.abs(cp) >= TH.csat_pts) {
      anomalies.push({ ...base, metric: 'csat', prior: pm.csat, current: cm.csat,
        delta_pts: cp, sample_size: ct.cr, direction: cp > 0 ? 'up' : 'down',
        _sev: Math.abs(cp) / TH.csat_pts });
    }
  }
}

anomalies.sort((a, b) => b._sev - a._sev);
const top = anomalies.slice(0, 5).map(({ _sev, ...rest }) => rest);

return [{ json: { trend, thresholds: TH, anomaly_count: anomalies.length, anomalies: top } }];
